Tool result: """
Universal AI Filler - Gemini-based form analyzer with semantic extraction.

Extends the base form filling logic with:
- extract_semantic_snapshot(): Captures form fields semantically (not CSS-based)
- analyze_and_map(): Uses Gemini to map profile to form fields
- execute_actions(): Fills fields using label-based locators
"""

import asyncio
import json
import re
from typing import Dict, List, Any, Optional, TypedDict
from loguru import logger


class FormAction(TypedDict):
    """Standard action format for form filling."""
    label: str        # Text label as visible to user
    field_type: str   # "text" | "select" | "radio" | "checkbox" | "textarea" | "number"
    value: str        # Value to fill


class UniversalAIFiller:
    """
    Gemini-powered form analyzer and filler.

    Uses semantic extraction (labels, aria-labels) instead of CSS selectors.
    Integrates with FormPatternStore for learning successful patterns.
    """

    def __init__(self, gemini_client: Optional[Any] = None):
        """
        Initialize the filler.

        Args:
            gemini_client: Optional GeminiClient instance (lazy-loaded if None)
        """
        self._gemini = gemini_client

    @property
    def gemini(self) -> Any:
        """Lazy-load GeminiClient."""
        if self._gemini is None:
            from src.ai.llm_client import GeminiClient
            self._gemini = GeminiClient()
        return self._gemini

    async def extract_semantic_snapshot(self, page: Any) -> Dict[str, Any]:
        """
        Extract a semantic snapshot of form fields from a page.

        Uses JavaScript to extract: labels, field types, options, aria-labels.
        Does NOT use CSS classes - only semantic information.

        Args:
            page: Playwright Page object

        Returns:
            {
                "questions": [
                    {
                        "label": str,
                        "field_type": str,
                        "options": list[str],
                        "aria_label": str
                    },
                    ...
                ]
            }
        """
        # JavaScript to extract form fields semantically
        js_code = """
        () => {
            const questions = [];

            // Helper to get label text
            function getLabelText(el) {
                // Try associated <label>
                if (el.id) {
                    const label = document.querySelector(`label[for="${el.id}"]`);
                    if (label) return label.textContent.trim();
                }
                // Try parent <label>
                const parentLabel = el.closest('label');
                if (parentLabel) return parentLabel.textContent.trim();
                // Try aria-label
                if (el.getAttribute('aria-label')) {
                    return el.getAttribute('aria-label').trim();
                }
                // Try placeholder for text inputs
                if (el.placeholder) return el.placeholder.trim();
                // Try name attribute
                if (el.name) return el.name.trim();
                return '';
            }

            // Helper to get field type
            function getFieldType(el) {
                const tagName = el.tagName.toLowerCase();
                if (tagName === 'textarea') return 'textarea';
                if (tagName === 'select') return 'select';
                if (tagName === 'input') {
                    const type = (el.type || 'text').toLowerCase();
                    if (type === 'radio') return 'radio';
                    if (type === 'checkbox') return 'checkbox';
                    if (type === 'number') return 'number';
                    return 'text';
                }
                return 'text';
            }

            // Helper to get options
            function getOptions(el) {
                const type = getFieldType(el);
                if (type === 'select') {
                    return Array.from(el.options || []).map(o => o.text.trim()).filter(Boolean);
                }
                if (type === 'radio' || type === 'checkbox') {
                    // Find all inputs in same group
                    const name = el.name;
                    const inputs = name ? document.querySelectorAll(`input[name="${name}"]`) : [el];
                    const options = [];
                    inputs.forEach(input => {
                        const label = getLabelText(input);
                        if (label) options.push(label);
                    });
                    return options;
                }
                return [];
            }

            // Find all form fields
            const selectors = [
                'input:not([type="hidden"]):not([type="submit"]):not([type="button"])',
                'textarea',
                'select'
            ];

            const seen = new Set();
            document.querySelectorAll(selectors.join(', ')).forEach(el => {
                // Skip already processed
                const key = el.id || el.name || `${el.tagName}-${Object.keys(seen).length}`;
                if (seen.has(key)) return;
                seen.add(key);

                const fieldType = getFieldType(el);
                const label = getLabelText(el);
                const options = getOptions(el);
                const ariaLabel = el.getAttribute('aria-label') || '';

                // Only include visible fields
                const rect = el.getBoundingClientRect();
                if (rect.width === 0 && rect.height === 0) return;
                if (el.type === 'hidden') return;

                questions.push({
                    label: label,
                    field_type: fieldType,
                    options: options,
                    aria_label: ariaLabel,
                    required: el.required || el.hasAttribute('required')
                });
            });

            // Also find fieldsets/legend for radio groups
            document.querySelectorAll('fieldset').forEach(fieldset => {
                const legend = fieldset.querySelector('legend');
                if (!legend) return;

                const radios = fieldset.querySelectorAll('input[type="radio"]');
                if (radios.length === 0) return;

                const labelText = legend.textContent.trim();
                const options = [];
                radios.forEach(radio => {
                    const label = getLabelText(radio);
                    if (label) options.push(label);
                });

                questions.push({
                    label: labelText,
                    field_type: 'radio',
                    options: options,
                    aria_label: '',
                    required: fieldset.hasAttribute('required') || radios[0]?.required
                });
            });

            return { questions: questions };
        }
        """

        try:
            result = await page.evaluate(js_code)
            logger.debug(f"Extracted {len(result.get('questions', []))} form fields")
            return result
        except Exception as e:
            logger.error(f"Failed to extract semantic snapshot: {e}")
            return {"questions": []}

    async def analyze_and_map(
        self,
        page: Any,
        profile: Dict[str, Any],
        snapshot: Optional[Dict[str, Any]] = None,
    ) -> List[FormAction]:
        """
        Analyze form fields and map profile data to form values using Gemini.

        Args:
            page: Playwright Page object
            profile: Candidate profile dict
            snapshot: Pre-extracted snapshot (optional, will extract if None)

        Returns:
            List of FormAction dicts with label, field_type, and value
        """
        # Get snapshot if not provided
        if snapshot is None:
            snapshot = await self.extract_semantic_snapshot(page)

        questions = snapshot.get("questions", [])
        if not questions:
            logger.warning("No questions found in snapshot")
            return []

        # Build prompt for Gemini
        prompt = f"""Analyze these form fields and map candidate profile data to form values.

Form Fields:
{json.dumps(questions, indent=2, ensure_ascii=False)}

Candidate Profile:
{json.dumps(profile, indent=2, ensure_ascii=False)}

For each field, determine the appropriate value from the profile.
Rules:
1. For text/textarea: write concise, factual answers from profile
2. For select/radio: choose ONE option that best matches profile
3. For checkbox: set value to "true" if applies, "false" if not
4. For number: use numeric value from profile

Respond with JSON array only, no markdown:
[
  {{"label": "field label", "field_type": "text", "value": "answer"}},
  ...
]

JSON response:"""

        try:
            response = await self.gemini.generate(prompt)

            # Parse JSON from response
            json_str = response.strip()
            if "```json" in json_str:
                json_str = json_str.split("```json")[1].split("```")[0]
            elif "```" in json_str:
                json_str = json_str.split("```")[1].split("```")[0]

            actions = json.loads(json_str.strip())

            # Validate actions
            valid_actions = []
            for action in actions:
                if not isinstance(action, dict):
                    continue
                if "label" not in action or "value" not in action:
                    continue
                valid_actions.append({
                    "label": str(action.get("label", "")),
                    "field_type": str(action.get("field_type", "text")),
                    "value": str(action.get("value", "")),
                })

            logger.info(f"Mapped {len(valid_actions)} fields via Gemini")
            return valid_actions

        except (json.JSONDecodeError, KeyError) as e:
            logger.error(f"Failed to parse Gemini mapping response: {e}")
            return []
        except Exception as e:
            logger.error(f"Gemini analyze_and_map error: {e}")
            return []

    async def execute_actions(
        self,
        page: Any,
        actions: List[FormAction],
    ) -> int:
        """
        Fill form fields using label-based locators.

        Uses fallback chain:
        1. page.get_by_label(label, exact=False) - Playwright near-exact match
        2. page.locator(f"[aria-label*='{label[:20]}' i]") - aria-label substring
        3. page.get_by_placeholder(label) - placeholder fallback

        Args:
            page: Playwright Page object
            actions: List of FormAction dicts

        Returns:
            Number of successfully filled fields
        """
        filled = 0

        for action in actions:
            label = action.get("label", "")
            field_type = action.get("field_type", "text")
            value = action.get("value", "")

            if not label or not value:
                continue

            try:
                # Find the element using label fallback chain
                element = None
                truncated_label = label[:50]  # Truncate for selectors

                # 1. Try get_by_label with exact=False
                try:
                    element = page.get_by_label(truncated_label, exact=False)
                    if await element.count() == 0:
                        element = None
                except Exception:
                    element = None

                # 2. Try aria-label attribute
                if element is None:
                    try:
                        aria_selector = f"[aria-label*='{label[:20]}']"
                        element = page.locator(aria_selector).first
                        if await element.count() == 0:
                            element = None
                    except Exception:
                        element = None

                # 3. Try placeholder
                if element is None:
                    try:
                        element = page.get_by_placeholder(label[:30], exact=False)
                        if await element.count() == 0:
                            element = None
                    except Exception:
                        element = None

                # 4. Try by name attribute as last resort
                if element is None:
                    # Convert label to potential name attribute
                    potential_name = label.lower().replace(" ", "_").replace("?", "")
                    try:
                        element = page.locator(f'[name="{potential_name}"]').first
                        if await element.count() == 0:
                            element = None
                    except Exception:
                        element = None

                if element is None:
                    logger.warning(f"Could not find element for label: {label[:30]}")
                    continue

                # Fill based on field type
                if field_type == "select":
                    await self._fill_select(element, value)
                    filled += 1
                    logger.debug(f"Filled select '{label[:30]}' with '{value[:30]}'")
                elif field_type == "radio":
                    await self._fill_radio(page, label, value)
                    filled += 1
                    logger.debug(f"Selected radio '{label[:30]}' option '{value[:30]}'")
                elif field_type == "checkbox":
                    await self._fill_checkbox(element, value)
                    filled += 1
                    logger.debug(f"Set checkbox '{label[:30]}' to '{value}'")
                elif field_type == "textarea":
                    await element.fill(value)
                    filled += 1
                    logger.debug(f"Filled textarea '{label[:30]}' with '{value[:50]}'")
                else:  # text, number, etc.
                    await element.fill(value)
                    filled += 1
                    logger.debug(f"Filled '{label[:30]}' with '{value[:30]}'")

            except Exception as e:
                logger.warning(f"Failed to fill '{label[:30]}': {e}")
                continue

        logger.info(f"Successfully filled {filled}/{len(actions)} fields")
        return filled

    async def _fill_select(self, element: Any, value: str) -> None:
        """Fill a select element with the given value."""
        # Try exact match first
        try:
            await element.select_option(label=value)
        except Exception:
            # Try partial match
            try:
                await element.select_option(label=value, exact=False)
            except Exception:
                # Try value attribute
                await element.select_option(value=value)

    async def _fill_radio(self, page: Any, label: str, value: str) -> None:
        """Select a radio button by label and value."""
        # Try to find radio by label containing value
        radio = page.locator(f'input[type="radio"]').filter(
            has_text=value
        ).first
        if await radio.count() > 0:
            await radio.click()
        else:
            # Fallback: try get_by_label with value
            await page.get_by_label(value, exact=False).click()

    async def _fill_checkbox(self, element: Any, value: str) -> None:
        """Set checkbox to checked or unchecked based on value."""
        should_check = value.lower() in ("true", "yes", "1", "checked")
        if should_check:
            await element.check()
        else:
            await element.uncheck()
